let windowSize = 3h;

// S54: Webshell Upload (UAVWebAudit_CL — Operator 없음, RequesterId 사용)
let S54 =
    UAVWebAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where WebshellSignatureDetected == true
    | extend Stage = 'S54', Operator = tostring(RequesterId)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

// S55: SUID Privilege Escalation (UAVWebAudit_CL — GtfobinsMatch/PrivilegeBefore/After)
let S55 =
    UAVWebAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where GtfobinsMatch == true
    | extend Stage = 'S55', Operator = tostring(RequesterId)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

// S56: Container Escape (UAVWebAudit_CL — EscapeMethod)
let S56 =
    UAVWebAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where isnotempty(EscapeMethod)
    | extend Stage = 'S56', Operator = tostring(RequesterId)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

// S57: Cron Persistence (UAVWebAudit_CL — CronEntry/InstalledBy)
let S57 =
    UAVWebAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where isnotempty(CronEntry)
    | extend Stage = 'S57', Operator = tostring(InstalledBy)
    | where isnotempty(Operator)
    | project TimeGenerated, Stage, Operator;

union S54, S55, S56, S57
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by Operator
| where StageCount >= 3
| extend CampaignType = "C16_웹셸_SUID_escape_cron_순수IT"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, Operator, StagesSeen, StageCount, CampaignType, StepSummary, Severity
